      "excerpt": "ebello a Vincence 14 , cite, x mille. \nDe Vincence a Padue 15, moult grande cite plus que Venize xvm milles. A Padue est le corps monseigneur Sainct Anthoine de l'ordre des freres mineurs de Sainct Frarn;oys. C'est une moult belle, notable et excellente\neglise, bien haulte, bien clere, grande, bien painte, le ceur moult decore, les chaires bien ouvres de menuyserie ; monseigneur Sainct A",
      "observations": [
        {
          "kind": "encounter",
          "title": "Arrival at vespers",
          "quote": "Nous arrivasmes a Venize le jeudi IIII de may, heure de vespres",
          "interpretation": "Collective arrival with an explicit time reference. “Vespers” dates the arrival within the day; it does not establish that bells were heard.",
          "paragraph": "p009",
          "status": "Provisional manual interpretation"
        },
        {
          "kind": "sight",
          "title": "Colours and images at Saint Mark’s",
          "quote": "Toute l'eglise et le ceur, chapelles et le tout est le plus pave en ymages de bestes, de oysiaulx, aigles, serpens, dragons, leons, de pierres quarres, cornues, rondes, blan ches, noires, vertes, jaunes, grises, perses, de toutes coulleurs ; et la plus part",
          "interpretation": "General visual description of mosaics during the Venice stay; no particular date assigned.",
          "paragraph": "p014",
          "status": "Provisional manual interpretation"
        },
        {
          "kind": "hearing",
          "title": "Music at Saint Salvator",
          "quote": "et est le joueur ung jeune enfant qui chante fort melodieu sement en jouant et y vont plusieurs pour l'ouyr plus que par devocion 1",
          "interpretation": "Description of singing and organ playing, and why people come to hear it; not an explicit personal hearing claim.",
          "paragraph": "p024",
          "status": "Provisional manual interpretation"
        },
        {
          "kind": "touch",
          "title": "Seeing and touching relics",
          "quote": "La chapelle est close et n'entre personne dedens si non une des religieuses laquelle est enfermee en la clef et fait toucher certaines choses. Maiz on voit le corps en chair et en os tout a son aise par ung treillis de fer 2",
          "interpretation": "Access to relics described as a general practice; distinguish touching performed by a nun from the narrator’s own actions.",
          "paragraph": "p024",
          "status": "Provisional manual interpretation"
        },
        {
          "kind": "practice",
          "title": "Water in Venice",
          "quote": "Item a Venize ne y a puys ne fontaine ne eaue doulce, sinon de la pluye qui chet sur les maisons et es rues, laquelle coule parmy sablons en cisternes faictes comme puys, et quant est faillie et il ne pleut point, il la convient acheter ou en aler querir en barques a vu milles de Venize, au canal, et la getter en leurs cours pour couler es cisternes.",
          "interpretation": "Description of water supply during the Venice stay; not evidence of personally tasting the water.",
          "paragraph": "p033",
          "status": "Provisional manual interpretation"
        }
      ],
      "date": "4 May 1480 · Thursday · vespers · Arrival in Venice. Arrival in Venice on Thursday 4 May 1480, at vespers.",
