        "paragraph": "p009",
        "quote": "(f05 r0)\nNous arrivasmes a Venize le jeudi IIII de may, heure de vespres et fault attendre le partement de la galee jusques au vie de juing que la galee partist. Et le jour du Sainct Sacrement, premier jour de juing, veismes aulcuns coucher en la galee sans retourner audit Venize 1 ."
