      "excerpt": "sner nous entrasmes en mer a bon vent et veismes, a jour faillir, gesir devant la cite de Raguze 5• \nEt est archevesche; les segnteurs sont segnieurs l'un apres l'autre cha cun ung moys 1 . La cite est petite, mais belle et riche, moitie en mer, d'aultre est une haulte montaigne de laquelle vient et ist une belle et grosse fontaine, laquelle faict mouldre VIII moullins, v droit contre la montaigne et III es fosses ; et est toute la vill",
