      "distance": "Arrival at supper time; III days here",
      "excerpt": "Le dimenche xv1e jour de juillet, heure de souper, arrivasmes en Cypre en une cite nommee Nymesson, evesche; et a este grant chose pour ville champestre car il n'y apperaist point de cloture, maiz a seullement ung petit chasteau; par apparence a este grant chose pour cite sans closture 4• \nLa grant eglise cathedrale",
